<?php
/** Content import uses real WordPress parsing/sanitization; DB/HTTP have their own runner. */
define('DOING_CRON',true);require __DIR__.'/m0/bootstrap.php';require __DIR__.'/../includes/study-engine/content.php';require __DIR__.'/study-engine/cross-sectional/support.php';
$tests=0;$failed=0;function pe_case($name,$fn){global $tests,$failed;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
use EIPSI\StudyEngine\Content\ResponseAdapter;
use EIPSI\StudyEngine\Content\TemplateAdapter;
use EIPSI\StudyEngine\Contracts\Canonical;
use EIPSI\StudyEngine\Engine\DefinitionCompiler;
use EIPSI\StudyEngine\Engine\Simulator;
$question=static function($type,$attrs=array()){return (new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_question('stable',$type,$attrs)))),'STUDY_UNIT','PUBLIC_UNIT',1);};
foreach(array('eipsi/campo-texto','eipsi/campo-textarea','eipsi/campo-radio','eipsi/campo-select','eipsi/campo-likert','eipsi/vas-slider','eipsi/consent-block') as $type)pe_case('Explicit block mapping '.$type,function()use($question,$type){$d=$question($type,array('options'=>'Sí, a veces;Nunca.','labels'=>'Bajo;Medio;Alto'));$g=(new DefinitionCompiler())->compile($d);pe_assert($g->node('Q_stable')['response_key']==='R_stable','Identity lost');});
pe_case('Stable identity does not change with label or position',function()use($question){$a=$question('eipsi/campo-texto');$b=$question('eipsi/campo-texto',array('label'=>'Otro texto'));$blocks=array(pe_block('eipsi/form-container',array(),array(pe_question('before'),pe_question('stable','eipsi/campo-texto',array('label'=>'Moved label')))));$moved=(new TemplateAdapter())->fromBlocks($blocks,'STUDY_UNIT','PUBLIC_UNIT',1);pe_assert($a['nodes'][2]['id']===$b['nodes'][2]['id']&&$a['nodes'][2]['response_key']===$b['nodes'][2]['response_key']&&$a['nodes'][2]['id']===$moved['nodes'][3]['id']&&$moved['nodes'][3]['position']===1,'Mutable identity');});
pe_case('Missing stable field identity rejects instead of using label',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block('eipsi/campo-texto',array('label'=>'Only label'))))),'S','P',1);},'INVALID_ID');});
pe_case('Duplicate stable question identity rejects',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_question('same'),pe_question('same')))),'S','P',1);},'DUPLICATE_LOGICAL_ID');});
pe_case('Explicit clone namespace regenerates logical IDs',function(){$d=(new TemplateAdapter())->fromBlocks(pe_blocks(),'S','P',1,array('clone_namespace'=>'COPY'));pe_assert($d['nodes'][2]['id']==='Q_COPY_q1','Clone reused identity');});
foreach(array('eipsi/campo-multiple','eipsi/randomization','eipsi/pool-join','unknown/scientific','core/html') as $type)pe_case('Unsupported block fails import '.$type,function()use($type){pe_reject(function()use($type){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block($type)))),'S','P',1);},'UNSUPPORTED_BLOCK');});
pe_case('Unknown decorative block explicit reject policy',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block('core/spacer')))),'S','P',1);},'UNSUPPORTED_BLOCK');});
pe_case('Legacy conditional logic cannot silently disappear',function()use($question){pe_reject(function()use($question){$question('eipsi/campo-radio',array('options'=>'Yes;No','conditionalLogic'=>array('enabled'=>true)));},'LEGACY_CONDITION');});
pe_case('Legacy container login cannot become anonymous silently',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array('requireLogin'=>true),array(pe_question('q')))),'S','P',1);},'LEGACY_FORM_WORKFLOW');});
pe_case('Hidden legacy page rejects',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block('eipsi/form-page',array('isHidden'=>true),array(pe_question('q')))))),'S','P',1);},'LEGACY_PAGE_WORKFLOW');});
pe_case('Unstructured HTML rejects instead of implicit parser',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block(null,array(),array(),'<input name="x">')))),'S','P',1);},'UNSTRUCTURED_HTML');});
pe_case('Duplicate options fail rather than collapse',function()use($question){pe_reject(function()use($question){$question('eipsi/campo-radio',array('options'=>'Sí;Sí'));},'DUPLICATE_OPTIONS');});
pe_case('Content HTML sanitized in snapshot',function(){$d=(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block('core/paragraph',array(),array(),'<p>Hello<script>alert(1)</script></p>')))),'S','P',1);pe_assert(strpos($d['nodes'][2]['content']['snapshot'],'<script')===false,'Script retained');});
pe_case('Local image required, external mutable URL rejected',function(){pe_reject(function(){(new TemplateAdapter())->fromBlocks(array(pe_block('eipsi/form-container',array(),array(pe_block('core/image',array('url'=>'https://outside.invalid/img.png'))))),'S','P',1);},'LOCAL_MEDIA_REQUIRED');});
pe_case('PageBreak creates directive not execution entity',function(){$d=pe_definition('pages');$g=(new DefinitionCompiler())->compile($d);$s=new Simulator($g,array('created_at'=>'2026-10-08T10:00:00Z'));$p=$s->presentation($s->nextAction()['payload']['assessment_execution_id']);pe_assert(count($p['pages'])===2,'Pages missing');foreach($s->snapshot()['instances'] as $i)pe_assert($i['definition_id']!=='PB_2','PageBreak execution');$without=$d;$without['nodes']=array_values(array_filter($without['nodes'],static function($n){return $n['id']!=='PB_2';}));foreach($without['nodes'] as &$n)if($n['id']==='G_PAGE_2')$n['position']=1;unset($n);(new DefinitionCompiler())->compile($without);pe_assert(Canonical::protocolHash($d)!==Canonical::protocolHash($without),'PageBreak hash unchanged');});
foreach(array('label','required','options','minLength','maxLength') as $field)pe_case('New content hash responds to '.$field,function()use($question,$field){$type=in_array($field,array('minLength','maxLength'),true)?'eipsi/campo-texto':'eipsi/campo-radio';$a=$question($type,array('options'=>'A;B'));$attrs=array('options'=>'A;B');$attrs[$field]=$field==='required'?false:($field==='minLength'?3:($field==='maxLength'?20:'Changed'));$b=$question($type,$attrs);pe_assert(Canonical::protocolHash($a)!==Canonical::protocolHash($b),'Hash unchanged');});
pe_case('Text HTTP value remains typed text',function()use($question){$d=$question('eipsi/campo-texto');pe_equal((new ResponseAdapter())->decode($d,array('R_stable'=>'0003'),array('Q_stable')),array('Q_stable'=>'0003'));});
pe_case('Numeric HTTP value becomes number',function()use($question){$d=$question('eipsi/vas-slider');pe_equal((new ResponseAdapter())->decode($d,array('R_stable'=>'3'),array('Q_stable')),array('Q_stable'=>3.0));});
pe_case('Boolean HTTP false is false, never truthy string',function()use($question){$d=$question('eipsi/consent-block');pe_equal((new ResponseAdapter())->decode($d,array('R_stable'=>'false'),array('Q_stable')),array('Q_stable'=>false));});
foreach(array('unknown','array','wrong_option','bound','step','length','min_length','email','bool') as $bad)pe_case('Server response rejection '.$bad,function()use($question,$bad){
 $type='eipsi/campo-texto';$attrs=array();$value='valid';$key='R_stable';
 if($bad==='unknown')$key='R_other';if($bad==='array')$value=array('payload');
 if($bad==='wrong_option'){$type='eipsi/campo-radio';$attrs['options']='A;B';$value='A';}
 if($bad==='bound'||$bad==='step'){$type='eipsi/vas-slider';$attrs['step']=2;$value=$bad==='bound'?'200':'3';}
 if($bad==='length'){$attrs['maxLength']=2;$value='long';}
 if($bad==='min_length'){$attrs['minLength']=10;$value='short';}
 if($bad==='email'){$attrs['fieldType']='email';$value='not email';}
 if($bad==='bool'){$type='eipsi/consent-block';$value='yes';}
 $d=$question($type,$attrs);pe_reject(function()use($d,$key,$value){(new ResponseAdapter())->decode($d,array($key=>$value),array('Q_stable'));},$bad==='unknown'?'QUESTION_NOT_OFFERED':'RESPONSE_');
});
pe_case('Consent semantic role alone does not terminate',function(){ $d=pe_definition('consent');$d['condition_rules']=array();$s=new Simulator((new DefinitionCompiler())->compile($d),array('created_at'=>'2026-10-08T10:00:00Z'));$s->dispatch(array('id'=>'NO_ROLE','kind'=>'ANSWER','data'=>array('question_id'=>'Q_consent','value'=>false)));pe_assert($s->nextAction()['kind']==='OPEN_ASSESSMENT','Role triggered rule');});
pe_case('Media reference affects protocol hash',function(){ $d=pe_definition();$snapshot=Canonical::json(array('attachment_id'=>1,'uri'=>'https://example.test/pinned/a.png','sha256'=>str_repeat('a',64)));$d['nodes'][]=array('kind'=>'CONTENT','id'=>'C_MEDIA','version_id'=>$d['id'],'parent_id'=>'E_ASSESSMENT','position'=>1,'type'=>'MEDIA','content'=>array('content_id'=>'CONTENT_MEDIA','version'=>1,'snapshot'=>$snapshot,'sha256'=>hash('sha256',$snapshot)),'durable_reference'=>array('uri'=>'https://example.test/pinned/a.png','sha256'=>str_repeat('a',64)));(new DefinitionCompiler())->compile($d);$changed=$d;$last=count($changed['nodes'])-1;$changed['nodes'][$last]['durable_reference']['uri']='https://example.test/pinned/b.png';$changed['nodes'][$last]['durable_reference']['sha256']=str_repeat('b',64);$snapshot=Canonical::json(array('attachment_id'=>2,'uri'=>'https://example.test/pinned/b.png','sha256'=>str_repeat('b',64)));$changed['nodes'][$last]['content']['snapshot']=$snapshot;$changed['nodes'][$last]['content']['sha256']=hash('sha256',$snapshot);(new DefinitionCompiler())->compile($changed);pe_assert(Canonical::protocolHash($d)!==Canonical::protocolHash($changed),'Pinned media ignored');});
echo "$tests tests, $failed failures\n";exit($failed?1:0);
